                    .child(name.clone()),
            )
            .when(dirty, |this| {
                this.child(
                    div()
                        .id(("file-tab-unsaved", ix))
                        .flex_none()
                        .size_2()
                        .rounded_full()
                        .bg(muted),
                )
            })
            .child(close)
            .into_any_element();
